package com.mayprep.blockwise;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.net.Uri;import android.provider.MediaStore;import android.speech.tts.TextToSpeech;import java.util.*;import java.io.*;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> chooser; TextToSpeech tts;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff163b2e);getWindow().setNavigationBarColor(0xff163b2e);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setPadding(0,0,0,0);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
 web.addJavascriptInterface(new Bridge(),"BlockwiseNative");tts=new TextToSpeech(this,status->{});
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(u.toString().startsWith("https://blockwise.local/")&&u.getFragment()!=null)return false;if("https".equals(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}}return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(r.getUrl().getHost()!=null&&r.getUrl().getHost().equals("blockwise.local")&&!r.getUrl().getPath().startsWith("/api/")){try{String path=r.getUrl().getPath();if(path.equals("/"))path="index.html";else path=path.substring(1);String mime=path.endsWith(".js")?"text/javascript":path.endsWith(".css")?"text/css":path.endsWith(".json")?"application/json":path.endsWith(".png")?"image/png":path.endsWith(".jpg")?"image/jpeg":path.endsWith(".svg")?"image/svg+xml":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open(path));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",null,new ByteArrayInputStream(new byte[0]));}}return null;}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;Intent i=p.createIntent();i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(i,44);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}});
 web.loadUrl("https://blockwise.local/"); }
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==44&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));chooser=null;}}
 @Override public void onBackPressed(){web.evaluateJavascript("if(document.querySelector('dialog')?.open)document.querySelector('dialog').close();else document.querySelector('[data-page=home]')?.click();",null);}
 @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}web.destroy();super.onDestroy();}
 public class Bridge {
  @JavascriptInterface public void exportBackup(String text){if(text.length()>50000)return;runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=29){ContentValues cv=new ContentValues();cv.put(MediaStore.Downloads.DISPLAY_NAME,"blockwise-backup-"+System.currentTimeMillis()+".json");cv.put(MediaStore.Downloads.MIME_TYPE,"application/json");Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,cv);try(OutputStream out=getContentResolver().openOutputStream(u)){out.write(text.getBytes("UTF-8"));}android.widget.Toast.makeText(MainActivity.this,"Saved in Downloads / Guardado en Descargas",0).show();}else{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Save backup / Guardar copia"));}}catch(Exception e){android.widget.Toast.makeText(MainActivity.this,"Could not save / No se pudo guardar",0).show();}});}
  @JavascriptInterface public void share(String text){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Share / Compartir"));});}
  @JavascriptInterface public void speak(String text,String lang){runOnUiThread(()->{int result=tts.setLanguage(lang.equals("es")?new Locale("es"):Locale.US);if(result<0){android.widget.Toast.makeText(MainActivity.this,"Install a voice for this language / Instala una voz para este idioma",0).show();return;}tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"fact");});}
  @JavascriptInterface public void stop(){tts.stop();}
 }
}
